insert into public.profile(data,published,display_order) values ('{"name": "Rohit Kumar Yadav", "headline": "Computer Science student building with AI, data & the web.", "introduction": "I turn curiosity into practical software. Exploring AI-powered applications, data workflows, and full-stack development—one project at a time.", "about": "I’m a Computer Science Engineering undergraduate at Guru Gobind Singh Indraprastha University, Delhi, graduating in 2029. My interests sit at the intersection of artificial intelligence, data science, and software engineering.\nI learn by building: working through a problem, testing an approach, and improving what I make. Internships in data science and web development have given me opportunities to apply that approach to real assignments. I’m now growing my skills in full-stack applications and useful automation.", "email": "rohitky9910@gmail.com", "linkedin": "https://linkedin.com/in/rohitkumaryadav1", "github": "https://github.com/rohitkumaryadav1", "x": "https://x.com/Rohityadav1__", "location": "Delhi, India", "focus": "Mail Trace Monitor · Chrome extension + FastAPI", "image": "initial/rohit-yellow-hoodie.webp", "resume_path": "initial/rohit-resume.pdf"}'::jsonb,true,0);
insert into public.projects(data,published,display_order) values ('{"title": "AI-Powered Resume Analyzer & Optimization Platform", "short_description": "Resume parsing, job-description matching, and LLM-assisted suggestions for more relevant applications.", "description": "An independent AI-powered resume optimization project that analyzes resumes against job descriptions, identifies skill gaps, and suggests content improvements.\nProject test results recorded in my resume include 85% keyword matching accuracy, 70% less manual resume review effort, and a 40% improvement in ATS compatibility scores through keyword optimization and suggestions.", "technologies": [], "status": "Completed", "github": "", "demo": "", "start_date": "", "completion_date": "", "featured": true, "image": "", "screenshots": [], "blog_url": "", "youtube_url": "", "blog_content": "", "highlights": ["Resume parsing and job-description matching", "Skill-gap detection and LLM-assisted suggestions"], "currently_building": false}'::jsonb,true,0);
insert into public.projects(data,published,display_order) values ('{"title": "AI-Powered Job Discovery & Outreach Automation Platform", "short_description": "Job aggregation, skill-based relevance scoring, and personalized recruiter outreach.", "description": "An independent platform combining job aggregation and filtering with skill-based opportunity matching and LLM-generated recruiter emails.\nResults recorded in my resume include analysis of 1,000+ job listings, 80% less manual job-search effort, and a 60% improvement in application workflow efficiency.", "technologies": [], "status": "Completed", "github": "", "demo": "", "start_date": "", "completion_date": "", "featured": true, "image": "", "screenshots": [], "blog_url": "", "youtube_url": "", "blog_content": "", "highlights": ["Job aggregation and skill-based relevance ranking", "Personalized recruiter outreach generation"], "currently_building": false}'::jsonb,true,1);
insert into public.projects(data,published,display_order) values ('{"title": "Mail Trace Monitor", "short_description": "A Chrome extension exploring email-open detection and tracked-link click events.", "description": "An ongoing independent Chrome extension and Python backend for understanding email engagement.\nThe extension includes Gmail compose detection, Chrome Storage preferences, tracking-record creation, and pre-send tracking-pixel insertion. The FastAPI backend includes a transparent-pixel endpoint, redirect-based link tracking, event recording, and analytics backed by SQLAlchemy and PostgreSQL.\nDevelopment is ongoing across the extension and backend. Mail Trace Monitor is currently In Progress. Email-open signals come from tracking-pixel requests and can be affected by email privacy settings.", "technologies": ["Chrome Extension", "HTML", "CSS", "JavaScript", "Python", "FastAPI", "Uvicorn", "SQLAlchemy", "PostgreSQL", "REST APIs", "Chrome Storage", "Git", "GitHub"], "status": "In Progress", "github": "", "demo": "", "start_date": "", "completion_date": "", "featured": false, "image": "", "screenshots": [], "blog_url": "", "youtube_url": "", "blog_content": "## Building Mail Trace Monitor\nMail Trace Monitor started with a practical question: how can an email sender get a clearer view of engagement? I am building a Chrome extension and a Python backend to explore email-open signals and tracked-link events. The project is still in progress.\n## Inside the Gmail workflow\nThe extension detects Gmail compose windows and adds a tracking control. Preferences are stored with Chrome Storage. The current implementation prepares a tracking record and inserts a small tracking pixel before the send action resumes.\n## From requests to events\nThe FastAPI backend serves the tracking pixel and records open events. It also creates tracked links, records click events, and redirects requests to the original destination. SQLAlchemy models organize email records, links, and events in PostgreSQL, while analytics endpoints summarize the recorded activity.\n## What I am learning\nThis build connects browser interfaces, API requests, and relational data. Working across those boundaries has been an opportunity to understand how a small browser interaction becomes a stored event and then an analytics response.\n## Still a work in progress\nI am continuing to develop the extension and backend together. Pixel requests are engagement signals, rather than proof that someone read an email; privacy features and image loading can affect them. These notes describe the current implementation, not a launched product.", "highlights": ["Gmail extension with per-email tracking controls", "FastAPI endpoints for open and click events", "PostgreSQL event storage and analytics"], "currently_building": true}'::jsonb,true,2);
insert into public.experiences(data,published,display_order) values ('{"organization": "Land Ports Authority of India (LPAI)", "position": "Data Science Intern", "parent_organization": "Ministry of Home Affairs, Government of India", "location": "New Delhi, India", "start_date": "2026-07-01", "completion_date": "2026-08-01", "description": "Worked on reproducible machine learning workflows and an interactive decision-support platform for Integrated Check Posts.", "responsibilities": ["Built a pipeline covering extraction, cleaning, and feature engineering for 13 years of LPAI reports.", "Compared Linear Regression, Random Forest, Extra Trees, and Gradient Boosting with automated model selection and evaluation.", "Built a Streamlit platform with 30+ KPIs, validation dashboards, feature importance, and future forecasting."], "achievements": ["80% less manual analysis effort and an R² of 0.72."], "technologies": ["Scikit-learn", "Streamlit", "Regression", "Feature Engineering", "Data Visualization"]}'::jsonb,true,0);
insert into public.experiences(data,published,display_order) values ('{"organization": "Cozmoh", "position": "Web Developer Intern", "parent_organization": "", "location": "Mumbai, India", "start_date": "2025-11-01", "completion_date": "2026-01-01", "description": "Developed responsive WordPress pages and collaborated with designers and stakeholders on client website assignments.", "responsibilities": ["Developed and optimized responsive pages with WordPress and Elementor.", "Implemented reusable UI components and improved page layouts and visual consistency.", "Translated business requirements into responsive web solutions in collaboration with designers and project stakeholders."], "achievements": ["mobile compatibility across all assigned pages, 30% fewer client revision requests, and 40% better visual consistency."], "technologies": ["WordPress", "Elementor"]}'::jsonb,true,1);
